"""Response models for indicators, support/resistance, summary, setups and backtests."""

from __future__ import annotations

from datetime import datetime
from typing import Literal

from pydantic import BaseModel, Field

from app.models.market import AssetType, Timeframe

DISCLAIMER = (
    "Educational technical analysis generated by algorithms from historical prices. "
    "It is not financial advice, not a recommendation, and no level, score or scenario is guaranteed."
)

IndicatorState = Literal["bullish", "bearish", "neutral", "overbought", "oversold", "high", "low", "insufficient_data", "unavailable"]


class IndicatorReading(BaseModel):
    key: str
    name: str
    category: Literal["trend", "momentum", "volatility", "volume"]
    values: dict[str, float | None]
    display: str
    state: IndicatorState
    interpretation: str
    params: dict[str, float | int | str]
    placement: Literal["overlay", "panel"]
    series_keys: list[str]


class AnalysisContext(BaseModel):
    symbol: str
    display_symbol: str
    asset_type: AssetType
    provider: str
    timeframe: Timeframe
    bars: int
    as_of: datetime
    last_price: float
    last_bar_complete: bool


class IndicatorsResponse(BaseModel):
    context: AnalysisContext
    times: list[int]
    series: dict[str, list[float | None]]
    future_times: list[int] = Field(default=[], description="Bar times after the last candle (Ichimoku projection)")
    future_series: dict[str, list[float | None]] = {}
    readings: list[IndicatorReading]
    notes: list[str] = []
    disclaimer: str = DISCLAIMER


# --------------------------------------------------------------------- support / resistance
LevelStatus = Literal["intact", "testing", "breakout", "breakdown", "reclaimed", "lost"]


class Level(BaseModel):
    id: str
    kind: Literal["support", "resistance"]
    tier: Literal["major", "minor"]
    price: float
    zone_low: float
    zone_high: float
    touches: int = Field(description="Distinct visits of price into the zone within the lookback")
    reactions: int = Field(description="Confirmed swing highs/lows inside the zone")
    strength: float = Field(ge=0, le=100)
    score_breakdown: dict[str, float]
    first_seen: datetime
    last_reaction: datetime
    distance: float = Field(description="Price units from the last price to the nearest zone edge (0 inside)")
    distance_pct: float
    status: LevelStatus
    status_detail: str
    status_changed_at: datetime | None = None
    historical_role: Literal["support", "resistance", "mixed"]


class ReferenceLevel(BaseModel):
    key: str
    name: str
    price: float
    period_start: datetime
    period_end: datetime
    distance: float
    distance_pct: float
    position: Literal["above", "below", "at"]
    source: Literal["observed"] = "observed"


class PivotLevels(BaseModel):
    basis: str
    method: str = "classic floor pivots: P=(H+L+C)/3, R1=2P-L, S1=2P-H, R2=P+(H-L), S2=P-(H-L), R3=H+2(P-L), S3=L-2(H-P)"
    levels: dict[str, float]


class FibLevel(BaseModel):
    ratio: float
    price: float


class FibonacciLevels(BaseModel):
    direction: Literal["up", "down"]
    swing_high: float
    swing_high_time: datetime
    swing_low: float
    swing_low_time: datetime
    levels: list[FibLevel]
    note: str


class TrendlinePoint(BaseModel):
    time: int
    price: float


class Trendline(BaseModel):
    kind: Literal["support", "resistance"]
    points: list[TrendlinePoint]
    anchors: list[TrendlinePoint]
    slope_per_bar: float
    current_value: float
    touches: int
    broken: bool
    description: str


class SupportResistanceParams(BaseModel):
    lookback: int
    swing_window: int
    tolerance: float
    major_threshold: float
    max_levels: int


class SupportResistanceResponse(BaseModel):
    context: AnalysisContext
    params: SupportResistanceParams
    atr: float | None
    levels: list[Level]
    nearest_support: Level | None
    nearest_resistance: Level | None
    reference_levels: list[ReferenceLevel]
    pivots: PivotLevels | None
    fibonacci: FibonacciLevels | None
    trendlines: list[Trendline]
    methodology: list[str]
    disclaimer: str = DISCLAIMER


# --------------------------------------------------------------------- summary
Direction = Literal["bullish", "bearish", "neutral", "insufficient_data"]


class FactorContribution(BaseModel):
    key: str
    name: str
    group: Literal["trend", "momentum", "volume"]
    weight: float
    value: float | None = Field(description="Normalized factor reading in [-1, 1]")
    contribution: float | None = Field(description="weight x value, in points of the weighted score")
    signal: Direction
    detail: str
    available: bool


class HorizonTrend(BaseModel):
    horizon: Literal["short", "medium", "long"]
    direction: Direction
    explanation: str


class MomentumSummary(BaseModel):
    state: Literal["positive", "negative", "mixed", "insufficient_data"]
    explanation: str


class VolatilitySummary(BaseModel):
    state: Literal["low", "moderate", "high", "insufficient_data"]
    atr: float | None
    atr_pct: float | None
    percentile: float | None
    baseline_bars: int
    squeeze: bool
    explanation: str


class VolumeSummary(BaseModel):
    state: Literal["confirming", "diverging", "neutral", "unavailable"]
    relative_volume: float | None
    explanation: str


class Condition(BaseModel):
    type: Literal["breakout", "breakdown", "bullish_reversal", "bearish_reversal"]
    active: bool
    level: float | None
    description: str


class KeyLevel(BaseModel):
    role: Literal["confirmation", "invalidation", "bullish_trigger", "bearish_trigger"]
    price: float
    description: str


class TechnicalEvent(BaseModel):
    time: int
    type: str
    direction: Literal["bullish", "bearish", "neutral"]
    description: str
    price: float | None = None


class OverallBias(BaseModel):
    bias: Literal["bullish", "bearish", "neutral"]
    score: float = Field(description="Weighted factor score in [-100, 100]. Not a probability.")
    bullish_threshold: float
    bearish_threshold: float
    factors_used: int
    factors_total: int
    explanation: str


class SummaryResponse(BaseModel):
    context: AnalysisContext
    overall: OverallBias
    factors: list[FactorContribution]
    conflicts: list[str]
    trend: list[HorizonTrend]
    momentum: MomentumSummary
    volatility: VolatilitySummary
    volume: VolumeSummary
    nearest_support: Level | None
    nearest_resistance: Level | None
    conditions: list[Condition]
    key_levels: list[KeyLevel]
    events: list[TechnicalEvent]
    methodology: list[str]
    disclaimer: str = DISCLAIMER


# --------------------------------------------------------------------- setups
class SetupTarget(BaseModel):
    price: float
    basis: str
    reward_risk: float | None


class TradeScenario(BaseModel):
    direction: Literal["bullish", "bearish"]
    available: bool
    unavailable_reason: str | None = None
    setup_type: str | None = None
    alignment: Literal["with_bias", "counter_bias", "neutral_bias"] | None = None
    entry_zone_low: float | None = None
    entry_zone_high: float | None = None
    entry_reference: float | None = None
    invalidation: float | None = None
    risk_per_unit: float | None = None
    targets: list[SetupTarget] = []
    reward_risk: float | None = Field(default=None, description="To the first target, from the entry reference")
    confirmation_conditions: list[str] = []
    invalidation_conditions: list[str] = []
    notes: list[str] = []


class SetupsResponse(BaseModel):
    context: AnalysisContext
    observed: dict[str, float | None] = Field(description="Observed market data the scenarios are built from")
    bullish: TradeScenario
    bearish: TradeScenario
    methodology: list[str]
    label: str = "Technical scenarios - not financial advice or predictions"
    disclaimer: str = DISCLAIMER


# --------------------------------------------------------------------- backtest
class BacktestTrade(BaseModel):
    direction: Literal["long", "short"]
    entry_time: int
    entry_price: float
    exit_time: int
    exit_price: float
    return_pct: float
    bars_held: int
    open: bool = False


class BacktestMetrics(BaseModel):
    trades: int
    win_rate: float | None
    avg_return_pct: float | None
    median_return_pct: float | None
    best_return_pct: float | None
    worst_return_pct: float | None
    profit_factor: float | None
    total_return_pct: float
    buy_and_hold_return_pct: float
    max_drawdown_pct: float
    exposure_pct: float
    avg_bars_held: float | None


class BacktestAssumptions(BaseModel):
    direction: Literal["long_only", "long_short"]
    entry_threshold: float
    exit_threshold: float
    commission_bps: float
    slippage_bps: float
    execution: str
    evaluation_start: int
    evaluation_end: int
    bars_evaluated: int


class BacktestResponse(BaseModel):
    context: AnalysisContext
    assumptions: BacktestAssumptions
    metrics: BacktestMetrics
    trades: list[BacktestTrade]
    equity_curve: list[TrendlinePoint]
    benchmark_curve: list[TrendlinePoint]
    caveats: list[str]
    disclaimer: str = DISCLAIMER
